/* Generic helpers over seed rows. Generated by Chakram; the same for every app. */
export type Op = 'eq' | 'neq' | 'gt' | 'gte' | 'lt' | 'lte' | 'in';
export type Where = { field: string; op: Op; value: unknown };
export type MetricFn = 'count' | 'sum' | 'avg' | 'min' | 'max';
export type MetricSpec = { fn: MetricFn; field?: string; where?: Where };
export type GroupBy = 'value' | 'day' | 'week' | 'month';
export type Row = object;

function get(row: object, field: string): unknown {
  return (row as Record<string, unknown>)[field];
}

function num(value: unknown): number {
  const n = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(n) ? n : 0;
}

export function matches(row: Row, where?: Where): boolean {
  if (!where) return true;
  const v = get(row, where.field);
  const w = where.value;
  switch (where.op) {
    case 'eq': return v === w || String(v) === String(w);
    case 'neq': return !(v === w || String(v) === String(w));
    case 'gt': return num(v) > num(w);
    case 'gte': return num(v) >= num(w);
    case 'lt': return num(v) < num(w);
    case 'lte': return num(v) <= num(w);
    case 'in': return Array.isArray(w) ? w.some((x) => x === v || String(x) === String(v)) : false;
    default: return true;
  }
}

export function filterRows<T extends Row>(rows: T[], where?: Where): T[] {
  return Array.isArray(rows) ? rows.filter((r) => matches(r, where)) : [];
}

export function metric<T extends Row>(rows: T[], spec: MetricSpec): number {
  const subset = filterRows(rows, spec.where);
  if (spec.fn === 'count' || !spec.field) return subset.length;
  const values = subset.map((r) => num(get(r, spec.field as string)));
  if (values.length === 0) return 0;
  const total = values.reduce((a, b) => a + b, 0);
  if (spec.fn === 'sum') return total;
  if (spec.fn === 'avg') return total / values.length;
  if (spec.fn === 'min') return Math.min(...values);
  return Math.max(...values);
}

export function count<T extends Row>(rows: T[], where?: Where): number {
  return metric(rows, { fn: 'count', where });
}
export function sum<T extends Row>(rows: T[], field: string, where?: Where): number {
  return metric(rows, { fn: 'sum', field, where });
}
export function avg<T extends Row>(rows: T[], field: string, where?: Where): number {
  return metric(rows, { fn: 'avg', field, where });
}

export function groupKey(value: unknown, by: GroupBy): string {
  if (by === 'value') return value === null || value === undefined ? '—' : String(value);
  const d = new Date(String(value));
  if (Number.isNaN(d.getTime())) return '—';
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  if (by === 'month') return `${y}-${m}`;
  if (by === 'week') {
    const day = new Date(Date.UTC(y, d.getUTCMonth(), d.getUTCDate()));
    const weekday = day.getUTCDay() || 7;
    day.setUTCDate(day.getUTCDate() - weekday + 1);
    return day.toISOString().slice(0, 10);
  }
  return `${y}-${m}-${String(d.getUTCDate()).padStart(2, '0')}`;
}

export type SeriesPoint = { key: string } & Record<string, number | string>;

/** One row per group key (sorted), with one numeric column per metric. */
export function series<T extends Row>(
  rows: T[],
  field: string,
  by: GroupBy,
  metrics: Array<{ key: string } & MetricSpec>,
): SeriesPoint[] {
  const groups = new Map<string, T[]>();
  for (const row of Array.isArray(rows) ? rows : []) {
    const k = groupKey(get(row, field), by);
    const bucket = groups.get(k);
    if (bucket) bucket.push(row);
    else groups.set(k, [row]);
  }
  return Array.from(groups.keys())
    .sort()
    .map((k) => {
      const point: SeriesPoint = { key: k };
      const bucket = groups.get(k) ?? [];
      for (const m of metrics) point[m.key] = metric(bucket, m);
      return point;
    });
}

export type Ranked = { id: string; label: string; value: number };

/** The top `n` groups of `field` by `spec`, labelled with `label(key)` when given. */
export function top<T extends Row>(
  rows: T[],
  field: string,
  spec: MetricSpec,
  n: number,
  label?: (key: string) => string,
): Ranked[] {
  return series(rows, field, 'value', [{ key: 'v', ...spec }])
    .map((p) => ({ id: p.key, label: label ? label(p.key) : p.key, value: num(p.v) }))
    .sort((a, b) => b.value - a.value)
    .slice(0, n > 0 ? n : undefined);
}

/** The `labelField` of the row whose id is `id`, or the id itself. */
export function lookup<T extends Row>(rows: T[], id: unknown, labelField: string): string {
  const row = (Array.isArray(rows) ? rows : []).find((r) => String(get(r, 'id')) === String(id));
  const value = row ? get(row, labelField) : undefined;
  return value === undefined || value === null ? String(id ?? '—') : String(value);
}

export function latest<T extends Row>(rows: T[], field: string, n: number): T[] {
  return [...(Array.isArray(rows) ? rows : [])]
    .sort((a, b) => String(get(b, field) ?? '').localeCompare(String(get(a, field) ?? '')))
    .slice(0, n > 0 ? n : undefined);
}
